$page_title='My profile';require 'includes/header.php';?>
<div class="container"><div class="page-heading"><div class="eyebrow">Account settings</div><h1>Your profile</h1></div><section class="form-card" style="max-width:650px"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Full name</label><input name="name" maxlength="100" required value="<?=e($_POST['name']??$u['name'])?>"></div><div class="field"><label>Email address</label><input type="email" name="email" required value="<?=e($_POST['email']??$u['email'])?>"></div><p class="helper">Member since <?=e(date('F Y',strtotime($u['created_at'])))?>.</p><button class="btn btn-primary">Save changes</button></form></section></div>
